import test from 'node:test';
import assert from 'node:assert/strict';
import { createCalculator } from '../../src/analysis/calculations.js';
import { graphData } from '../../src/analysis/graph-data.js';
import { fitGraph } from '../../src/analysis/regression.js';
import { createWorkspace } from '../../src/analysis/workspace.js';
import { timeBounds, rangeSampleIds } from '../../src/analysis/scope.js';

// Expected values were executed against the original analysis modules at
// Cho-WH/bme280 59c5c149450f970bace2deaa183857c275595853, not generated by this port.
test('BMP280 calculation, scope and regression match the fixed original fixture', () => {
  const context = { channels: [
    { id: 'temperatureC', name: '온도', unit: '℃', calculable: true },
    { id: 'pressureHpa', name: '압력', unit: 'hPa', calculable: true },
  ] };
  const definitions = [
    { id: 'calc-k', name: '절대온도', unit: 'K', lhs: { kind: 'column', columnId: 'temperatureC' }, op: '+', rhs: { kind: 'constant', value: 273.15 } },
    { id: 'calc-ratio', name: 'P/T', unit: 'hPa/K', lhs: { kind: 'column', columnId: 'pressureHpa' }, op: '/', rhs: { kind: 'column', columnId: 'calc-k' } },
  ];
  const temperatures = [20, 21, 23, 24, 25, 26, 27, 28], pressures = [1000, 1004, 1010, 1013, 1016, 1020, 1022, 1027];
  const raw = temperatures.map((temperatureC, index) => ({ sampleId: index + 1, receivedAt: 1700000000000 + index * 1000,
    values: { temperatureC, pressureHpa: pressures[index] }, validity: { temperatureC: index === 4 ? 'out-of-range' : 'valid', pressureHpa: 'valid' } }));
  const original = structuredClone(raw), calculate = createCalculator(definitions, [], context);
  const samples = raw.map(sample => ({ ...sample, calculations: calculate(sample) }));
  assert.deepEqual(samples.map(s => s.calculations['calc-k'].value), [293.15, 294.15, 296.15, 297.15, null, 299.15, 300.15, 301.15]);
  assert.deepEqual(samples.map(s => s.calculations['calc-ratio'].value), [3.4112229234180456, 3.413224545300017, 3.4104339017389838, 3.409052667003197, null, 3.4096607053317736, 3.40496418457438, 3.4102606674414746]);
  assert.equal(samples[4].calculations['calc-k'].reason, samples[4].calculations['calc-ratio'].reason);
  const state = { graph: { xColumnId: 'calc-k', yColumnId: 'pressureHpa', type: 'scatter', view: 'measured', connectGaps: false },
    appliedIds: [1, 2, 3, 4, 5, 6, 7], tableLastSampleId: 7, exclusions: [{ sampleId: 3, reason: '장치 이동' }], calculatedColumns: definitions };
  const graph = graphData(samples, state, [], context), result = fitGraph(graph, 3).result;
  assert.deepEqual(graph.points.map(p => p.sampleId), [1, 2, 4, 6, 7]);
  assert.deepEqual(graph.excludedPoints, [{ x: 296.15, y: 1010, sampleId: 3 }]);
  assert.equal(graph.invalidCount, 1); assert.equal(graph.xUnit, 'K'); assert.equal(graph.yUnit, 'hPa');
  assert.equal(result.slope, 3.161290322580645); assert.equal(result.intercept, 73.68709677419349);
  assert.equal(result.rSquared, 0.9972310674235082); assert.equal(result.xIntercept, -23.30918367346937);
  assert.deepEqual(raw, original);
});

test('arbitrary channels use identical workspace commands and expose independent evidence snapshots', () => {
  const context = { channels: [{ id: 'light', name: '밝기', unit: null, calculable: true }],
    defaultGraph: { xColumnId: 'receivedAt', yColumnId: 'light', type: 'line' }, analysisTemplates: [] };
  const snapshot = { run: { id: 'generic', context }, samples: [2, 4, 6].map((light, i) => ({ runId: 'generic', sampleId: i + 1,
    receivedAt: 1700000000000 + i * 1000, values: { light }, validity: { light: 'valid' } })), workspace: null };
  const store = { getSnapshot: () => structuredClone(snapshot), getState: () => ({ writable: true }), saveWorkspace: workspace => { snapshot.workspace = structuredClone(workspace); } };
  const workspace = createWorkspace({ store });
  assert.equal(workspace.getSummary().invalidCount, 0);
  assert.deepEqual(workspace.getState().calculationTemplates, []);
  assert.throws(() => workspace.preparePreset('kelvin'));
  workspace.setTrendEnabled(true); workspace.captureReflection();
  assert.equal(workspace.getGraphData().regression.result.slope, 2);
  const evidence = workspace.getReflectionModel(); evidence.points[0].y = 999;
  const rows = workspace.getRows(); rows[0].values.light = 999;
  workspace.exclude([2], '장치 이동');
  assert.equal(workspace.getReflectionModel().points[0].y, 2);
  assert.equal(workspace.getRows()[0].values.light, 2);
  assert.equal(snapshot.samples[0].values.light, 2);
  assert.equal(workspace.getReflectionModel().points.length, 3);
  assert.equal(workspace.getGraphData().points.length, 2);
});

test('graph gaps preserve invalid and excluded positions without filtering source readings away', () => {
  const context = { channels: [{ id: 'pressure', name: '압력', unit: 'hPa', calculable: true }], connection: { staleMs: 5000 } };
  const samples = [0, 100, 6100, 6200, 6300, 6400, 6000].map((receivedAt, i) => ({ sampleId: i + 1,
    receivedAt, values: { pressure: 1000 + i }, validity: { pressure: i === 3 ? 'error' : 'valid' } }));
  const state = { graph: { xColumnId: 'receivedAt', yColumnId: 'pressure', type: 'line', connectGaps: false },
    appliedIds: samples.map(p => p.sampleId), tableLastSampleId: 7, exclusions: [{ sampleId: 5 }], calculatedColumns: [] };
  const graph = graphData(samples, state, [], context);
  assert.deepEqual(graph.points.map(p => p.sampleId), [1, 2, 3, 6, 7]);
  assert.deepEqual(graph.excludedPoints.map(p => p.sampleId), [5]); assert.equal(graph.invalidCount, 1);
  assert.equal(graph.line.filter(p => p.y === null).length, 4);
  state.graph.connectGaps = true;
  const connected = graphData(samples, state, [], context);
  assert.equal(connected.line.filter(p => p.y === null).length, 3);
  assert.deepEqual(connected.points, graph.points);
});

test('missing timestamps never become epoch zero or enter a time range', () => {
  const context = { channels: [{ id: 'light', name: '밝기' }],
    defaultGraph: { xColumnId: 'sampleId', yColumnId: 'light', type: 'scatter' } };
  const snapshot = { run: { id: 'untimed', context }, samples: [1, 2].map(sampleId => ({ sampleId, receivedAt: null,
    values: { light: sampleId * 3 }, validity: { light: 'valid' } })), workspace: null };
  const store = { getSnapshot: () => structuredClone(snapshot), getState: () => ({ writable: true }), saveWorkspace: value => { snapshot.workspace = structuredClone(value); } };
  const workspace = createWorkspace({ store });
  assert.equal(timeBounds(snapshot.samples), null);
  assert.deepEqual(rangeSampleIds(snapshot.samples, { startAt: 0, endAt: 1000 }), []);
  assert.deepEqual(workspace.getGraphData().points.map(p => [p.x, p.y]), [[1, 3], [2, 6]]);
  workspace.setGraph({ xColumnId: 'receivedAt', yColumnId: 'light', type: 'line' });
  assert.equal(workspace.getGraphData().points.length, 0);
  assert.equal(workspace.getGraphData().invalidCount, 2);
  const mixed = [...snapshot.samples, { sampleId: 3, receivedAt: 1000 }];
  assert.deepEqual(timeBounds(mixed), { startAt: 1000, endAt: 1000, origin: 1000 });
  assert.deepEqual(rangeSampleIds(mixed, { startAt: 0, endAt: 1000 }), [3]);
});
